const input = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const A = input[0];
const L = input[1];
const N = input[2];

let bestId = -1;
let bestArea = Infinity;

for (let i = 0; i < N; i++) {
  const X = input[3 + 2 * i];
  const Y = input[4 + 2 * i];

  // A foto cabe (considerando rotação da moldura / foto) se:
  // (A <= X e L <= Y) ou (A <= Y e L <= X)
  if ((A <= X && L <= Y) || (A <= Y && L <= X)) {
    const area = X * Y;
    // área desperdiçada = X*Y - A*L; como A*L é fixo, basta minimizar X*Y.
    // Percorrendo em ordem de identificador, "<" garante o menor id em empates.
    if (area < bestArea) {
      bestArea = area;
      bestId = i + 1;
    }
  }
}

console.log(bestId);
